begin;
do $$
declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();adm uuid:=gen_random_uuid();p uuid:=gen_random_uuid();t uuid:=gen_random_uuid();s uuid:=gen_random_uuid();path text;pub text;n integer;
begin
 path:=a||'/'||s||'.mp3';pub:='custom/'||s||'.mp3';
 insert into auth.users(id,email) values(a,a||'@example.invalid'),(b,b||'@example.invalid'),(adm,adm||'@example.invalid');
 insert into public.sb_profiles(id,display_name) values(a,'Contributor'),(b,'Other'),(adm,'Admin');
 update public.sb_account_access set status='approved' where user_id in(a,b,adm);
 insert into soundbar_private.sb_admins(user_id) values(adm);
 perform set_config('request.jwt.claim.sub',a::text,true);execute 'set local role authenticated';
 insert into public.sb_playlists(id,name) values(p,'Test');
 insert into public.sb_tracks(id,playlist_id,name,audio_path,filename) values(t,p,'My track',a||'/'||t||'.mp3','track.mp3');
 insert into storage.objects(bucket_id,name,metadata) values('soundbar-audio',a||'/'||t||'.mp3','{"size":128,"mimetype":"audio/mpeg"}');
 insert into storage.objects(bucket_id,name,metadata) values('soundbar-submissions',path,'{"size":128,"mimetype":"audio/mpeg"}');
 insert into public.sb_library_submissions(id,source_track_id,name,author,license,credit,consent,object_path,filename,mime,file_size) values(s,t,'Shared','Contributor','CC BY 4.0','Credit',true,path,'track.mp3','audio/mpeg',128);
 update storage.objects set metadata='{"size":999,"mimetype":"audio/mpeg"}' where bucket_id='soundbar-submissions' and name=path;get diagnostics n=row_count;if n<>0 then raise exception 'Pending snapshot mutable';end if;
 begin update public.sb_library_submissions set status='approved' where id=s;raise exception 'Self approval allowed';exception when insufficient_privilege then null;end;
 begin perform public.sb_review_submission(s,'approved',s::text);raise exception 'Nonadmin RPC allowed';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',b::text,true);
 if exists(select 1 from public.sb_library_submissions where id=s) then raise exception 'Other user sees submission';end if;
 if exists(select 1 from storage.objects where bucket_id='soundbar-submissions' and name=path) then raise exception 'Other user sees media';end if;
 perform set_config('request.jwt.claim.sub',a::text,true);delete from public.sb_tracks where id=t;
 if not exists(select 1 from public.sb_library_submissions where id=s and source_track_id is null) then raise exception 'Original deletion destroys submission';end if;
 perform set_config('request.jwt.claim.sub',adm::text,true);
 if exists(select 1 from storage.objects where bucket_id='soundbar-audio' and name=a||'/'||t||'.mp3') then raise exception 'Admin can browse private originals';end if;
 if not exists(select 1 from storage.objects where bucket_id='soundbar-submissions' and name=path) then raise exception 'Admin cannot review chosen snapshot';end if;
 begin perform public.sb_review_submission(s,'approved',s::text);raise exception 'Approval without published file allowed';exception when raise_exception then if sqlerrm='Approval without published file allowed' then raise;end if;end;
 insert into public.sb_library_tracks(id,name,object_path,audio_url,filename) values(s::text,'Shared',pub,'https://fcmsojjtkiehsobbkjnr.supabase.co/storage/v1/object/public/soundbar-library/'||pub,'track.mp3');
 perform public.sb_review_submission(s,'approved',s::text);
 if not exists(select 1 from public.sb_library_submissions where id=s and status='approved' and reviewed_by=adm and library_id=s::text) then raise exception 'Admin approval not persisted';end if;
 perform public.sb_review_submission(s,'approved',s::text);
 execute 'reset role';
end $$;
rollback;
